function escHtml(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }
window.lyricEsc = escHtml;
const LYRIC_IMG_TOKEN = "\u0001";
window.__lyricImgPool = [];
window.safeTemplateReplace = function(tpl, token, value) {
    let text = String(tpl).split(token).join(value);
    if (text.includes("{{LYRIC_IMG_POOL}}")) {
        const pool = window.__lyricImgPool || [];
        text = text.split("{{LYRIC_IMG_POOL}}").join(window.escapeScriptJson(JSON.stringify(pool)));
    }
    return text;
};
window.escapeScriptEmbed = function(s) {
    return String(s).replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${").replace(/<\//g, "<\\/");
};
window.escapeScriptJson = function(s) { return String(s).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029"); };


function ncmHomeUrl(value) {
    const url = String(value == null ? "" : value).trim();
    if (/^https?:\/\//i.test(url)) return url;
    const m = url.match(/^orpheus:\/\/nm\/([A-Za-z]+)\/home\?id=(\d+)/);
    return m ? "https://music.163.com/#/" + m[1] + "?id=" + m[2] : "";
}

function lyricImgToken(picUrl) {
    if (!picUrl || !/^https?:\/\//i.test(picUrl)) return "";
    const img = '<img src="' + escHtml(picUrl) + '?param=50y50" class="lyric-img">';
    window.__lyricImgPool.push(img);
    return LYRIC_IMG_TOKEN + (window.__lyricImgPool.length - 1) + LYRIC_IMG_TOKEN;
}


function lyricCreatorToken(name, avatarUrl, homepageUrl) {
    const safeName = escHtml(name);
    const img = avatarUrl && /^https?:\/\//i.test(avatarUrl)
        ? '<img src="' + escHtml(avatarUrl) + '?param=50y50" class="lyric-img">' : "";
    const home = homepageUrl && /^https?:\/\//i.test(homepageUrl) ? escHtml(homepageUrl) : "";
    const inner = img + safeName;
    if (!home) {
        if (!img) return safeName;
        window.__lyricImgPool.push(inner);
    } else {
        window.__lyricImgPool.push('<span class="lyric-creator" data-w="' + home + '">' + inner + '</span>');
    }
    return LYRIC_IMG_TOKEN + (window.__lyricImgPool.length - 1) + LYRIC_IMG_TOKEN;
}

const decodeMetaEntities = (text) => String(text || "").replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (full, code) => { const lower = code.toLowerCase(); if (lower === "amp") return "&"; if (lower === "lt") return "<"; if (lower === "gt") return ">"; if (lower === "quot") return '"'; if (lower === "apos") return "'"; const value = lower.startsWith("#x") ? parseInt(lower.slice(2), 16) : parseInt(lower.slice(1), 10); return Number.isFinite(value) && value >= 0 && value <= 0x10ffff && !(value >= 0xd800 && value <= 0xdfff) ? String.fromCodePoint(value) : full; });
const isContributorText = (text) => /^(?:滚动歌词贡献者|翻译歌词贡献者)\s*[:：]/.test(decodeMetaEntities(String(text || "").replace(/\u0001\d+\u0001/g, "").trim()));
const isMetaText = (text) => /^(?:作词|作曲|编曲|制作人|混音|母带|监制|和声|吉他|贝斯|鼓手|录音|滚动歌词贡献者|翻译歌词贡献者|词|曲)[^:：]{0,30}[:：]/.test(decodeMetaEntities(String(text || "").replace(/\u0001\d+\u0001/g, "").trim()));
window.lyricStripImgTokens = function(s) { return String(s).replace(/\u0001\d+\u0001/g, ""); };
window.lyricRestoreImgTokens = function(s) {
    return String(s).replace(/\u0001(\d+)\u0001/g, (m, i) => window.__lyricImgPool[Number(i)] || "");
};


function assignMetaTimes(items, tailStep) {
    let i = 0;
    while (i < items.length) {
        if (!items[i].isMeta) { i++; continue; }
        let j = i;
        while (j < items.length && items[j].isMeta) j++;
        const run = items.slice(i, j);
        const prev = i > 0 ? items[i - 1] : null;
        const next = j < items.length ? items[j] : null;
        const base = prev ? prev.time + (prev.duration || 0) : 0;
        if (next) {
            const span = Math.max(0, next.time - base);
            run.forEach((meta, k) => { meta.time = Math.round(base + span * (k + 1) / (run.length + 1)); });
        } else {
            run.forEach((meta, k) => { meta.time = Math.round(base + (tailStep || 500) * (k + 1)); });
        }
        i = j;
    }
    return items;
}

function metaTextKey(text) {
    return decodeMetaEntities(String(text || ""))
        .replace(/[\u200b-\u200d\u2060\ufeff]/g, "")
        .replace(/\u0001\d+\u0001/g, "")
        .replace(/<[^>]*>/g, "")
        .trim()
        .replace(/\s+/g, " ")
        .replace(/：/g, ":")
        .replace(/\s*:\s*/g, ":")
        .toLocaleLowerCase();
}

const META_KNOWN_TYPES = new Set(["作词", "作曲", "编曲", "制作人", "混音", "母带", "监制", "和声", "吉他", "贝斯", "鼓手", "录音", "滚动歌词贡献者", "翻译歌词贡献者"]);
function metaTypeKey(text) {
    const s = metaTextKey(text);
    const m = s.match(/^([^:]{1,40})\s*:/);
    if (!m) return "";
    const label = m[1].replace(/\s+/g, "").normalize("NFKC");
    const alias = {
        "词": "作词", "词作者": "作词", "作词人": "作词", "lyricist": "作词", "lyricsby": "作词", "lyrics": "作词", "lyric": "作词",
        "曲": "作曲", "曲作者": "作曲", "作曲人": "作曲", "composer": "作曲", "composedby": "作曲", "composed": "作曲", "compose": "作曲", "composition": "作曲",
        "编曲人": "编曲", "arranger": "编曲", "arrangedby": "编曲", "arranged": "编曲", "arrange": "编曲",
        "producer": "制作人", "制作": "制作人",
        "混音师": "混音", "mixing": "混音",
        "母带师": "母带", "mastering": "母带",
        "监制人": "监制",
        "和声编写": "和声",
        "吉他手": "吉他", "guitar": "吉他",
        "贝斯手": "贝斯", "bass": "贝斯",
        "鼓": "鼓手", "鼓手": "鼓手", "drums": "鼓手",
        "录音师": "录音", "recording": "录音"
    };
    if (alias[label]) return alias[label];
    const tokens = String(m[1]).replace(/[（(][^）)]*[）)]/g, " ").split(/[\s/|、,;；&·+]+/).map(token => token.replace(/[^\p{L}\p{N}]/gu, "").normalize("NFKC").toLowerCase()).filter(Boolean);
    for (const token of tokens) {
        const mapped = alias[token] || token;
        if (META_KNOWN_TYPES.has(mapped)) return mapped;
    }
    return label;
}

function dedupeMetaItems(items, endMetas) {
    const seen = new Set();
    const filter = (list) => list.filter(item => {
        if (!item || !item.isMeta) return true;
        const key = metaTypeKey(item.text) || metaTextKey(item.text);
        if (!key || seen.has(key)) return false;
        seen.add(key);
        return true;
    });
    return [filter(items), filter(endMetas)];
}

function lyrictolyric(args) {
    window.__lyricImgPool.length = 0;
    const input = args.lyricinput; const output = args.lyricoutput; const content = String(args.content || "").trim();
    if (input === output) return content;
    try {
        if (input === "packlrc" && output === "arc") {
            const lines = content.split("\n").filter(line => line.trim());
            let items = [];
            let endMetas = [];
            let hasLyricStarted = false;
            lines.forEach(line => {
                const trimLine = line.trim();
                if (trimLine.startsWith("{")) {
                    try {
                        const meta = JSON.parse(trimLine);
                        if (Array.isArray(meta.c)) {
                            const metaTime = Number(meta.t);
                            const text = meta.c.reduce((acc, item) => {
                                const name = (item && (item.c !== undefined ? item.c : item.tx)) || "";
                                const avatar = item && (item.a || item.li);
                                const home = item && ncmHomeUrl(item.w || item.homepage || item.url || item.or);
                                if (name && (avatar || home)) return acc + lyricCreatorToken(String(name), avatar, home);
                                return acc + lyricImgToken(avatar) + name;
                            }, "");
                            const lineItem = { time: Number.isFinite(metaTime) ? metaTime : 0, text: text, isMeta: true, isContributor: isContributorText(text) };
                            
                            if (lineItem.isContributor) {
                                endMetas.push(lineItem);
                            } else {
                                items.push(lineItem);
                            }
                        }
                    } catch (e) {}
                } 
                else {
                    const timePrefix = trimLine.match(/^((?:\[\d+:\d+(?:[.:]\d{1,3})?\]\s*)+)/);
                    const timeMatches = timePrefix ? [...timePrefix[1].matchAll(/\[(\d+):(\d+)(?:[.:](\d{1,3}))?\]/g)] : [];
                    if (timeMatches.length) {
                        hasLyricStarted = true;
                        const last = timeMatches[timeMatches.length - 1];
                        const text = trimLine.slice(timePrefix[1].length).trim();
                        timeMatches.forEach(match => {
                            const m = parseInt(match[1]);
                            const s = parseInt(match[2]);
                            const ms = parseInt((match[3] || "").padEnd(3, "0") || "0");
                            const meta = isMetaText(text);
                            const lineItem = { time: m * 60000 + s * 1000 + ms, text: text, isMeta: meta, isContributor: meta && isContributorText(text) };
                            if (lineItem.isContributor) endMetas.push(lineItem);
                            else items.push(lineItem);
                        });
                    }
                }
            });
        
            [items, endMetas] = dedupeMetaItems(items, endMetas);
            assignMetaTimes(items, 500);
            const lastItem = items.length ? items[items.length - 1] : null;
            const lastEndTime = lastItem ? lastItem.time + (lastItem.duration || 0) : 0;
            endMetas.forEach((meta, idx) => {
                meta.time = lastEndTime + 500 * (idx + 1);
            });
            const allLines = [...items, ...endMetas];
            let reconstructedLrc = allLines.map(l => {
                const totalMs = l.time;
                const m = Math.floor(totalMs / 60000);
                const remain = totalMs % 60000;
                const s = Math.floor(remain / 1000);
                const ms = remain % 1000;
                const timeStr = `[${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}.${ms.toString().padStart(2, "0")}]`;
                if (l.isMeta) return JSON.stringify({ t: l.time, c: [{ tx: l.text }] });
                return timeStr + l.text;
            }).join("\n");
        
            return JSON.stringify({ type: "lrc", lyric: reconstructedLrc });
        }
        
        if (input === "packyrc" && output === "arc") {
            const lines = content.split("\n").filter(line => line.trim());
            let items = [];
            let endMetas = [];
            let hasLyricStarted = false;
            lines.forEach(line => {
                const trimLine = line.trim();
                if (trimLine.startsWith("{")) {
                    try {
                        const meta = JSON.parse(trimLine);
                        if (Array.isArray(meta.c)) {
                            const metaTime = Number(meta.t);
                            const text = meta.c.reduce((acc, item) => {
                                const name = (item && (item.c !== undefined ? item.c : item.tx)) || "";
                                const avatar = item && (item.a || item.li);
                                const home = item && ncmHomeUrl(item.w || item.homepage || item.url || item.or);
                                if (name && (avatar || home)) return acc + lyricCreatorToken(String(name), avatar, home);
                                return acc + lyricImgToken(avatar) + name;
                            }, "");
                            const metaItem = { time: Number.isFinite(metaTime) ? metaTime : 0, text: text, isMeta: true, isContributor: isContributorText(text) };
                            
                            if (metaItem.isContributor) {
                                endMetas.push(metaItem);
                            } else {
                                items.push(metaItem);
                            }
                        }
                    } catch (e) {}
                } else {
                    hasLyricStarted = true;
                    const match = trimLine.match(/^\[(\d+),(\d+)\]/);
                    if (match) {
                        const wordMatches = [...line.matchAll(/\((\d+),(\d+),\d+\)([\s\S]*?)(?=\(\d+,\d+,\d+\)|$)/g)];
                        const words = wordMatches.map(m => ({ text: m[3], o: parseInt(m[1]), d: parseInt(m[2]) }));
                        const text = words.map(word => word.text).join("");
                        const meta = isMetaText(text);
                        const lineItem = { time: parseInt(match[1]), words: words, text: text, isMeta: meta, isContributor: meta && isContributorText(text), duration: parseInt(match[2]) };
                        if (lineItem.isContributor) endMetas.push(lineItem);
                        else items.push(lineItem);
                    }
                }
            });
            [items, endMetas] = dedupeMetaItems(items, endMetas);
            assignMetaTimes(items, 500);
            const lastItem = items.length ? items[items.length - 1] : null;
            const lastEndTime = lastItem ? lastItem.time + (lastItem.duration || 0) : 0;
            endMetas.forEach((meta, idx) => {
                meta.time = lastEndTime + 500 * (idx + 1);
            });
            const allLines = [...items, ...endMetas];
            const result = { type: "krc", lyric: {} };
            allLines.forEach((line, i) => {
                if (line.isMeta) {
                    result.lyric[i + 1] = { words: [{ text: line.text, o: line.time, d: 1 }], isMeta: true, isContributor: line.isContributor || false, startTime: line.time };
                } else {
                    result.lyric[i + 1] = { words: line.words, isMeta: false, isContributor: false, startTime: line.time, duration: line.duration || 0 };
                }
            });
            return JSON.stringify(result);
        }
    } catch (e) { return content; }
    return content;
}
